import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import { applyTierFrontmatter, classifyThreadTier, isPrivateAddress, parsePrivateSenders } from '../src/core/google/ingest-tiers.ts';
import { PGLiteEngine } from '../src/core/pglite-engine.ts';
import { __setChatTransportForTests, configureGateway, resetGateway } from '../src/core/ai/gateway.ts';
import { runLoopsCatchup } from '../src/core/google/loop-catchup.ts';
import { runLoopsExtract } from '../src/core/google/loops-extract.ts';
import type { GmailMessageMeta, GoogleSourceState } from '../src/core/google/types.ts';
import { CredentialError } from '../src/core/creds/errors.ts';
import { isConversationFactsEligiblePage } from '../src/core/facts/conversation-types.ts';
import { parseMarkdown } from '../src/core/markdown.ts';

test('parsePrivateSenders: comments, case, @domain and malformed lines', () => {
  const list = parsePrivateSenders([
    '# heading',
    'Alice-Example@Example.Invalid  # trailing comment',
    '@Private.Example.Invalid',
    'not-an-address',
    '@',
    '@a@b.invalid',
    '',
  ].join('\n'));
  expect([...list.addresses]).toEqual(['alice-example@example.invalid']);
  expect([...list.domains]).toEqual(['private.example.invalid']);
  expect(list.hashes).toHaveLength(2);
  expect(isPrivateAddress('ALICE-EXAMPLE@example.invalid', list)).toBe(true);
  expect(isPrivateAddress('bob@private.example.invalid', list)).toBe(true);
  expect(isPrivateAddress('bob@sub.private.example.invalid', list)).toBe(false);
  expect(isPrivateAddress('bob@example.invalid', list)).toBe(false);
});

test('parsePrivateSenders: a list with no usable entries is refused', () => {
  for (const text of ['', '# only a comment\n\n', 'garbage\n@\n']) {
    let err: unknown;
    try { parsePrivateSenders(text); } catch (e) { err = e; }
    expect(err).toBeInstanceOf(CredentialError);
    expect((err as CredentialError).code).toBe('private_senders_unreadable');
  }
});

test('applyTierFrontmatter: re-tiering replaces keys, full drops the opt-outs, private sets visibility', () => {
  const page = '---\ntitle: T\n---\nbody\n';
  const record = applyTierFrontmatter(page, 'record');
  expect(record).toBe('---\ntitle: T\ningest_tier: record\nfacts_backstop: false\nextract_atoms: false\nconversation_parseable: false\n---\nbody\n');
  expect(applyTierFrontmatter(record, 'record')).toBe(record);
  expect(applyTierFrontmatter(record, 'full')).toBe('---\ntitle: T\ningest_tier: full\n---\nbody\n');
  const priv = applyTierFrontmatter(record, 'private');
  expect(priv.match(/ingest_tier:/g)).toHaveLength(1);
  expect(priv).toContain('ingest_tier: private');
  expect(priv).toContain('visibility: private');
  expect(priv).toContain('extract_atoms: false');
  expect(applyTierFrontmatter('no frontmatter', 'record')).toBe('no frontmatter');
});

test('the conversation-facts extractor never reads record or private email pages', () => {
  const page = '---\ntype: email\ntitle: T\n---\nPeer: Can you send the statement?\n';
  const eligible = (markdown: string) =>
    isConversationFactsEligiblePage({ type: 'email', frontmatter: parseMarkdown(markdown).frontmatter }, ['email']);
  const record = applyTierFrontmatter(page, 'record');
  const priv = applyTierFrontmatter(record, 'private');
  expect(eligible(record)).toBe(false);
  expect(eligible(priv)).toBe(false);
  const full = applyTierFrontmatter(priv, 'full');
  expect(full).not.toContain('conversation_parseable');
  expect(eligible(full)).toBe(true);
});

describe('model reads and the private list on a brain', () => {
  const SRC = 'tiersrc';
  const OWNER = 'owner@example.invalid';
  let engine: PGLiteEngine;
  beforeAll(async () => {
    engine = new PGLiteEngine();
    await engine.connect({});
    await engine.initSchema();
    __setChatTransportForTests(async () => { throw new Error('no model may read these pages'); });
    await engine.executeRaw(`INSERT INTO sources (id, name, config) VALUES ($1, $1, '{"kind":"google"}'::jsonb) ON CONFLICT (id) DO NOTHING`, [SRC]);
  });
  afterAll(async () => {
    __setChatTransportForTests(null);
    resetGateway();
    configureGateway({ embedding_model: 'openai:text-embedding-3-large', embedding_dimensions: 1536, env: { ...process.env } });
    await engine.disconnect();
  });

  const message = (threadId: string, from: string, labelIds: string[]): GmailMessageMeta => ({
    id: threadId + '01', threadId, from, fromAddress: from, to: [OWNER], cc: [], subject: 'Note',
    dateIso: new Date(Date.now() - 86_400_000).toISOString(), internalDateMs: Date.now() - 86_400_000,
    labelIds, listUnsubscribe: false, calendarMethod: null, bodyText: 'Can you send the statement?',
  });

  test('a bulk thread from a private sender is private, not dropped', async () => {
    const thread = { threadId: 'aa11', account: OWNER, messages: [message('aa11', 'statements@bank.example.invalid', ['INBOX', 'CATEGORY_PROMOTIONS'])] };
    const list = parsePrivateSenders('@bank.example.invalid\n');
    expect(await classifyThreadTier(engine, thread, new Set([OWNER]), null)).toBe('none');
    expect(await classifyThreadTier(engine, thread, new Set([OWNER]), list)).toBe('private');
  });

  test('the loops catch-up and the extract job never send record or private pages to a model', async () => {
    await engine.setConfig('loops.extraction_enabled', 'true');
    const day = new Date(Date.now() - 86_400_000).toISOString();
    const put = (slug: string, threadId: string, extra: Record<string, unknown>) => engine.putPage(slug,
      { type: 'email', title: 'Note', compiled_truth: 'Peer: Can you send the statement?', frontmatter: { thread_id: threadId, date: day, ...extra } }, { sourceId: SRC });
    await put('emails/full-1111', '1111', { ingest_tier: 'full' });
    await put('emails/record-2222', '2222', { ingest_tier: 'record', facts_backstop: false, extract_atoms: false });
    await put('emails/private-3333', '3333', { ingest_tier: 'private', facts_backstop: false, extract_atoms: false, visibility: 'private' });
    const report = await runLoopsCatchup({ engine, sourceId: SRC, state: {} as GoogleSourceState, log: () => {}, myAddresses: new Set([OWNER]),
      inFlight: new Set<string>(), fetchThread: async (threadId: string) => ({ threadId, account: OWNER, messages: [message(threadId, 'peer@example.invalid', ['INBOX'])] }) });
    expect(report).toMatchObject({ enqueued: 1, skipped_reason: null });
    const jobs = await engine.executeRaw<{ slug: string }>("SELECT data->>'slug' AS slug FROM minion_jobs WHERE name = 'loops_extract'");
    expect(jobs.map((j) => j.slug)).toEqual(['emails/full-1111']);
    for (const slug of ['emails/record-2222', 'emails/private-3333']) {
      expect(await runLoopsExtract(engine, { slug, sourceId: SRC })).toMatchObject({ status: 'skipped', reason: 'model_reads_off' });
    }
  });
});
